(()=>{
const select=document.querySelector('#detail-size'),photo=document.querySelector('.detail-product-photo');if(!select||!photo)return;
const packs={'200L':['editorial/plastic-drum-branded.png','ถังพลาสติกสีฟ้า 200 ลิตร'],'20L':['editorial/gallon20-branded-v6.png','แกลลอน 20 ลิตร'],'5L':['editorial/gallon5-branded-v6.png','แกลลอน 5 ลิตร'],'1L':['editorial/gallon1-branded-v6.png','แกลลอน 1 ลิตร'],'1000L':['editorial/ibc1000-branded-v6.png','IBC Tank 1,000 ลิตร'],'ISO Tank':['local/iso-tank-profile.png','ISO Tank ตู้ใหญ่']};
const update=()=>{const p=packs[select.value];if(!p)return;photo.innerHTML=`<div class="original-pack cutout-pack branded-plastic"><img src="/assets/${p[0]}" alt="${p[1]}${select.value==='ISO Tank'?'':' พร้อมโลโก้ Etohcols'}" width="1024" height="1024"></div>`;const stage=document.querySelector('.warehouse-stage');stage?.classList.toggle('is-iso',select.value==='ISO Tank');const label=document.getElementById('detail-pack-label');if(label)label.textContent=p[1];document.querySelector('.detail-spec>small').textContent=select.value==='ISO Tank'?'ภาพ ISO Tank จาก Company Profile':'';const delivery=document.querySelector('.detail-logistics-link');if(delivery){const url=new URL(delivery.href);url.pathname=select.value==='ISO Tank'?'/iso-tank/':'/logistics/';url.searchParams.set('size',select.value);url.searchParams.set('quantity',document.querySelector('#buy-quantity')?.value||'1');delivery.href=url.pathname+url.search;}const quote=document.querySelector('.product-quote');if(quote){const url=new URL(quote.href);url.searchParams.set('size',select.value);url.searchParams.set('quantity',document.querySelector('#buy-quantity')?.value||'1');quote.href=url.pathname+url.search;}};select.addEventListener('change',update);document.querySelector('#buy-quantity')?.addEventListener('input',update);update();
})();
